export async function studioAPI(path,data){const r=await fetch('/api/studio/'+path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});let v={};try{v=await r.json();}catch{if(r.ok)throw Error('The server sent an unexpected reply. Please try again.');}if(!r.ok)throw Error(v.error||(r.status===413?'Your design is too large to send. Use smaller images, or use Download PDF and email it to info@satingraphic.ca.':'Could not complete the operation (error '+r.status+'). Please try again.'));return v;}
