const LANDSCAPE=['business-cards','brochures','yard-signs','vinyl-banners'];
function newDesign(product){const vehicle=!!product.views;return {productId:product.id,options:{sizeIndex:0,orientation:LANDSCAPE.includes(product.id)||vehicle||product.group==='Apparel'&&product.sizes[0].width>product.sizes[0].height?'landscape':'portrait',quantity:product.quantity[0],rounded:false,fold:product.folds[0]||'',sideCount:vehicle?product.views.length:product.group==='Apparel'?4:product.twoSided?2:1,values:Object.fromEntries(product.options.map(o=>[o.key,o.options[0].value])),selections:{},coupon:'',...(vehicle?{vehicleModel:product.vehicleModels?.[0]||'',vehicleColour:'white'}:{})},sides:Array.from({length:sideSlots(product)},()=>({background:'#ffffff',layers:[]})),assets:[],notes:''};}
// Older saved designs predate per-view vehicle sides; pad them so every view can be edited.
function normalise(design,product){while(design.sides.length<sideSlots(product))design.sides.push({background:design.options.vehicleColour==='black'?'#1e2023':'#ffffff',layers:[]});if(product.views)design.options.sideCount=product.views.length;return design;}
const dataURL=blob=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob);});

/* ---------- fonts: lazy Google Fonts for display, embedded woff2 for exports ---------- */
const FONT_INFO=Object.fromEntries(FONT_LIBRARY.map(f=>[f.name,f]));
const fontCSSText={},fontEmbedded={},fontLoaded={};let localFontCSS=null;
async function googleCSS(name){if(fontCSSText[name])return fontCSSText[name];const fam=encodeURIComponent(name).replace(/%20/g,'+');if(googleCSS.offline)throw Error('Google Fonts unreachable');for(const axis of [':ital,wght@0,400;0,700;1,400;1,700',':wght@400;700','']){let r;try{r=await fetch(`https://fonts.googleapis.com/css2?family=${fam}${axis}&display=swap`);}catch{googleCSS.offline=true;throw Error('Google Fonts unreachable');}if(r.ok){fontCSSText[name]=await r.text();return fontCSSText[name];}}throw Error('Font unavailable: '+name);}
// Load a font for on-screen use (preview, canvas). Safe to call repeatedly.
export function ensureFont(name){const info=FONT_INFO[name];if(!info||info.source!=='google')return Promise.resolve();if(!fontLoaded[name])fontLoaded[name]=googleCSS(name).then(css=>{const s=document.createElement('style');s.dataset.studioFont=name;s.textContent=css;document.head.append(s);return Promise.all([document.fonts.load(`400 24px "${name}"`),document.fonts.load(`700 24px "${name}"`)]).catch(()=>{});}).catch(()=>{delete fontLoaded[name];});return fontLoaded[name];}
async function localFonts(){if(localFontCSS!==null)return localFontCSS;let out='';for(const [name,path] of [['Inter','inter-latin.woff2'],['Vazirmatn','vazirmatn.woff2']]){try{const b=await (await fetch('/satin/fonts/'+path)).blob();out+=`@font-face{font-family:'${name}';src:url('${await dataURL(b)}') format('woff2');font-weight:100 900;}`;}catch{}}return localFontCSS=out;}
// Embeds only the subsets a print shop needs (latin, latin-ext, arabic) of every Google font used in a design.
async function embedGoogleFont(name){if(fontEmbedded[name])return fontEmbedded[name];const css=await googleCSS(name);const blocks=[...css.matchAll(/\/\*\s*([a-z-]+)\s*\*\/\s*(@font-face\s*{[^}]*})/g)];const keep=(blocks.length?blocks.filter(b=>['latin','latin-ext','arabic'].includes(b[1])).map(b=>b[2]):css.match(/@font-face\s*{[^}]*}/g)||[]);let out='';for(const block of keep){const url=block.match(/url\((https:\/\/fonts\.gstatic\.com[^)]+)\)/)?.[1];if(!url)continue;try{const b=await (await fetch(url)).blob();out+=block.replace(url,"'"+(await dataURL(b))+"'").replace(/font-display:[^;]*;/,'');}catch{}}return fontEmbedded[name]=out;}
export function fontsUsed(model){return [...new Set(model.sides.flatMap(s=>s.layers.filter(l=>l.type==='text').map(l=>l.font)))];}
async function fontCSSFor(model){let css=await localFonts();for(const name of fontsUsed(model))if(FONT_INFO[name]?.source==='google'){try{css+=await embedGoogleFont(name);}catch{}}return css;}

