// Print SVGs embed every uploaded image; very large photos are re-encoded (max 4500 px, the original upload is still attached to the order) so the file stays within the server's size limit.
const liteCache={};
async function liteEmbedded(){const out={...embedded};for(const [id,url] of Object.entries(embedded)){if(typeof url!=='string'||url.length<4e6||url.startsWith('data:image/svg'))continue;if(!liteCache[id]){try{const img=await loadImage(url),k=Math.min(1,4500/Math.max(img.naturalWidth||img.width,img.naturalHeight||img.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round((img.naturalWidth||img.width)*k));c.height=Math.max(1,Math.round((img.naturalHeight||img.height)*k));c.getContext('2d').drawImage(img,0,0,c.width,c.height);let d=c.toDataURL('image/webp',.92);if(!d.startsWith('data:image/webp'))d=url.startsWith('data:image/jpeg')?c.toDataURL('image/jpeg',.92):c.toDataURL('image/png');liteCache[id]=d.length<url.length?d:url;}catch{liteCache[id]=url;}}out[id]=liteCache[id];}return out;}
async function printPayload(model){const fonts=await fontCSSFor(model),lite=await liteEmbedded();const out={artwork:activeSides(model).map(i=>({side:i,key:sideViews(product)[i]?.key||'side-'+(i+1),svg:svgArtwork(model,i,lite,fonts,true)})),dimensions:dimensions(product,model.options)};try{out.print=rasterCache.change===change&&rasterCache.id===designId?rasterCache.data:await printRasters(model,fonts);}catch{}return out;}
 // Print-ready PDF in the browser: one page per printed side, MediaBox = trim + bleed, TrimBox = trim, 300 DPI rasters.
 let rasterCache={change:-1,id:'',data:null};
