 async function addOrder(){if(busy||!$('[data-approve]').checked||!mockup){status('Generate and approve the mockup first.',true);return;}setBusy(true);const se=$('[data-submitted]');if(se)se.innerHTML='';try{await save();const caps=await studioAPI('session');let printFiles={};if(caps.clientArtwork)printFiles=await printPayload(structuredClone(design));let v;try{v=await studioAPI('approve',{id:cartId,designId,approved:true,preview:proof,mockup,...printFiles});}catch(e){/* older servers reject embedded web fonts: retry once with plain-font SVGs (the print rasters keep the real fonts) */if(!printFiles.artwork||!/safety check|rejected/i.test(e.message))throw e;const lite=await liteEmbedded();printFiles.artwork=activeSides(design).map(i=>({side:i,key:sideViews(product)[i]?.key||'side-'+(i+1),svg:svgArtwork(design,i,lite,'',true)}));v=await studioAPI('approve',{id:cartId,designId,approved:true,preview:proof,mockup,...printFiles});}cartId=crypto.randomUUID();status('Design submitted. Opening the product page…');let target=fromProduct&&/^\/satin(?:\/[a-z0-9-]+)*\/?$/.test(fromProduct)?fromProduct:localizedPath(product.path);if(!target.endsWith('/'))target+='/';const link=new URL(target,location.origin);link.searchParams.set('designId',v.id);if(rule)link.searchParams.set('values',JSON.stringify(priceInputs(product,design.options,rule)));location.assign(link.pathname+link.search);}catch(e){status(e.message,true);submitError(e.message);}finally{setBusy(false);}}
