 function selectSide(i){finishEditing();side=i;selected=null;renderStage();renderLayers();renderPages();}
 function layerCommand(command){const layers=design.sides[side].layers,index=layers.findIndex(l=>l.id===selected);if(index<0)return;snapshot();const l=layers[index];if(command==='delete'){layers.splice(index,1);selected=null;}if(command==='duplicate'){const copy={...l,id:crypto.randomUUID(),x:Math.min(2,l.x+.03),y:Math.min(2,l.y+.03)};layers.push(copy);selected=copy.id;}if(command==='forward'&&index<layers.length-1)[layers[index],layers[index+1]]=[layers[index+1],layers[index]];if(command==='backward'&&index>0)[layers[index],layers[index-1]]=[layers[index-1],layers[index]];if(command==='front'){layers.splice(index,1);layers.push(l);}if(command==='back'){layers.splice(index,1);layers.unshift(l);}if(command==='center'){l.x=.5-l.w/2;l.y=.5-l.h/2;}if(command==='copy'){clipboard=structuredClone(l);history.pop();status('Copied');return;}changed();renderStage();renderLayers();}
