 function openMenu(x,y){const el=$('[data-menu]'),l=currentLayer();const items=l?[['duplicate','Duplicate','Ctrl+D'],['copy','Copy','Ctrl+C'],['paste','Paste','Ctrl+V',!clipboard],null,['front','Bring to front'],['forward','Bring forward','Ctrl+]'],['backward','Send backward','Ctrl+['],['back','Send to back'],null,['center','Centre on page'],...(l.type==='text'?[['edit','Edit text','Enter']]:[]),null,['delete','Delete','Del']]:[['paste','Paste','Ctrl+V',!clipboard],['add-text','Add text','T'],['background','Change background'],null,['shortcuts','Keyboard shortcuts','?']];el.innerHTML=items.map(i=>i?`<button type="button" role="menuitem" data-menu-cmd="${i[0]}" ${i[3]?'disabled':''}><span>${esc(t(i[1]))}</span>${i[2]?`<kbd>${i[2]}</kbd>`:''}</button>`:'<hr>').join('');const hr=host.getBoundingClientRect();el.hidden=false;el.style.left=Math.min(x-hr.left,hr.width-230)+'px';el.style.top=Math.min(y-hr.top,hr.height-el.offsetHeight-8)+'px';el.querySelector('button:not([disabled])')?.focus();}
